    .trim();
// AG5: Heurística para detectar si el usuario mencionó un campo explícitamente
const userMentionedField = (field, userText) => {
  const norm = (v) => String(v ?? '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase().replace(/[^a-z0-9ñ\s]/g, ' ').replace(/\s+/g, ' ').trim();
  const text = norm(userText);

  if (field === 'city') {
    // Ciudades chilenas comunes + patrones
    const cities = ['santiago', 'valparaiso', 'viña', 'vina', 'concon', 'quilpue', 'villa alemana', 'limache', 'olmue', 'casablanca', 'curacavi', 'puente alto', 'la florida', 'las condes', 'providencia', 'ñuñoa', 'maipu', 'san bernardo', 'melipilla', 'talagante', 'buin', 'padre hurtado', 'la granja', 'san ramon', 'pedro aguirre cerda', 'lo espejo', 'cerrillos', 'quilicura', 'huechuraba', 'renca', 'independencia', 'recoleta', 'conchali', 'huechuraba', 'colina', 'lantana', 'til til', 'linares', 'rancagua', 'san antonio'];
    return cities.some(c => text.includes(c)) || /\b(en|desde|hacia|para)\s+[a-zñ]+\b/.test(text);
  }

  if (field === 'service') {
    // Productos y servicios de Hormiglass
    const products = ['adocesped', 'adocreto', 'adoquin', 'baldosa', 'pastelon', 'duriente', 'bloque', 'placa', 'poste', 'solera', 'solerilla', 'tapa', 'camara', 'basas', 'pilar', 'borde', 'piscina', 'macetero', 'cilindro', 'cemento', 'pigmento', 'piedra', 'serena', 'cuarzo', 'fuget', 'alambre', 'puas', 'concertina', 'vidrio', 'templado', 'espejo', 'incer', 'ceramico', 'porcelanato', 'instalacion', 'venta', 'mantenimiento', 'reparacion', 'movimiento', 'tierra', 'replanteo', 'excavacion', 'vaciado', 'transporte'];
    return products.some(p => text.includes(p)) || /\b(servicio|instalacion|venta|mantenimiento|reparacion)\b/.test(text);
  }

  if (field === 'requirement') {
    // Patrones de requisito: cantidades, necesidades, plazos
    return /\b(necesito|quiero|requiero|ocupo|necesitaria|quisiera)\b/.test(text)
      || /\b(instalar|reparar|comprar|cambiar|renovar|reemplazar|poner|colocar|hacer)\b/.test(text)
      || /\b(metro|m2|m\d*|cantidad|unidad|pieza)\b/.test(text)
      || /\b(urjencia|urgente|para|hasta|plazo|fecha|cuando|antes|despues)\b/.test(text)
      || /\b(color|gris|blanco|negro|rojo|cafe|beige|cafe|arena|natural)\b/.test(text);
  }

  return false;
};

const decodeStepState = (encoded) => {
